
(async()=>{
const root=document.getElementById('br-rail'),canvas=root.querySelector('canvas'),ctx=canvas.getContext('2d'),button=root.querySelector('button'),status=root.querySelector('.rr-status'),cue=root.querySelector('.rr-cue');
const assets={"court": "data:image/webp;base64,", "wing": "data:image/png;base64,", "marker": "data:image/png;base64,", "rim": "data:image/png;base64,"};
const images={};await Promise.all(Object.entries(assets).map(async([key,url])=>{const im=new Image();im.src=url;await im.decode();images[key]=im}));
let phase='fight',opening=0,travel=0,frame=0,disposed=false;
const ease=t=>t*t*(3-2*t),reduced=()=>matchMedia('(prefers-reduced-motion: reduce)').matches;
function img(key,x,y,w,h){ctx.drawImage(images[key],x,y,w,h)}
function courtView(x,y,w,h){ctx.drawImage(images.court,x,y,w,h)}
function door(x,y,w,h,flip){ctx.save();if(flip){ctx.translate(x+w,y);ctx.scale(-1,1);x=0;y=0}ctx.drawImage(images.wing,5,20,178,310,x,y,w,h);ctx.restore()}
function draw(){
 ctx.imageSmoothingEnabled=false;ctx.clearRect(0,0,960,600);
 // The destination remains visible beyond the threshold throughout the advance.
 courtView(0,0,960,600);
 if(phase!=='arrival'){
  const t=ease(travel),scale=1+3.4*t,portalX=480,portalY=235;
  ctx.save();ctx.translate(480,300);ctx.scale(scale,scale);ctx.translate(-portalX,-(300+(portalY-300)*t));
  // One complete painted foreground scene, with an opening into the next scene.
  ctx.save();ctx.beginPath();ctx.rect(-150,-200,1260,1050);ctx.rect(350,115,260,268);ctx.clip('evenodd');
  courtView(-145,-65,1240,775);ctx.fillStyle='rgba(32,22,28,.13)';ctx.fillRect(-150,-200,1260,1050);ctx.restore();
  // Pixel artwork frames and overlaps the threshold so there are no floating edges.
  img('wing',153,-35,285,435);img('marker',588,-35,178,440);
  ctx.fillStyle='#201821';ctx.fillRect(344,105,272,13);ctx.fillRect(339,105,12,279);ctx.fillRect(610,105,12,279);
  const offset=ease(opening)*139;
  ctx.save();ctx.beginPath();ctx.rect(350,115,260,268);ctx.clip();door(350-offset,115,131,268,false);door(480+offset,115,131,268,true);ctx.restore();
  // Real foreground stone layers move past faster than the distant court.
  img('rim',-70-t*70,343+t*32,360,280);img('marker',770+t*100,215+t*65,210,465);
  if(opening>0&&opening<1){ctx.fillStyle='#b9a085';for(let i=0;i<22;i++){const a=(i*37)%260;ctx.globalAlpha=(1-opening)*.45;ctx.fillRect(350+a,372+opening*35+(i%4)*4,3+i%4,3)}}ctx.globalAlpha=1;
  ctx.restore();
  // Last few steps resolve into the full painted destination, never a 3D scene.
  if(t>.72){ctx.globalAlpha=(t-.72)/.28;courtView(0,0,960,600);ctx.globalAlpha=1}
 }
 const shade=ctx.createLinearGradient(0,420,0,600);shade.addColorStop(0,'#21182100');shade.addColorStop(1,'#211821b8');ctx.fillStyle=shade;ctx.fillRect(0,420,960,180);
}
function ui(){
 const busy=phase==='opening'||phase==='advance';button.disabled=busy;cue.hidden=phase!=='open';
 button.textContent=phase==='fight'?'Clear area (mock)':phase==='open'?'Advance through passage':phase==='arrival'?'Replay':'Advancing…';
 status.textContent=phase==='fight'?'Win here. The passage stays shut until the area is clear.':phase==='opening'?'Area cleared. The stone doors are opening.':phase==='open'?'The fight is over. Your next area is through that doorway.':phase==='advance'?'Moving through the cleared passage…':'Next area reached. Stop here and fight again.';
 root.querySelector('.rr-state').textContent=phase==='arrival'?'NEXT ENCOUNTER':phase==='fight'?'CLEAR THIS AREA':phase==='opening'?'AREA SECURED':'ADVANCE';
 root.querySelector('h2').textContent=phase==='arrival'?'The inner court':'The sealed passage';root.querySelector('.rr-step').textContent=phase==='arrival'?'02 / 02':'01 / 02';
}
function save(){window.openai?.setWidgetState?.({modelContent:{proposal:'2.5D clear then advance',phase},privateContent:{railVersion:1,phase}}).catch(()=>{})}
function animate(kind,duration){phase=kind;ui();const start=performance.now();function step(now){if(disposed)return;const v=reduced()?1:Math.min(1,(now-start)/duration);if(kind==='opening')opening=v;else travel=v;draw();if(v<1)frame=requestAnimationFrame(step);else{phase=kind==='opening'?'open':'arrival';ui();draw();save()}}frame=requestAnimationFrame(step)}
button.addEventListener('click',()=>{if(phase==='fight')animate('opening',1100);else if(phase==='open')animate('advance',2400);else if(phase==='arrival'){phase='fight';opening=travel=0;ui();draw();save()}});
function restore(state){const p=state?.privateContent;if(p?.railVersion!==1)return;cancelAnimationFrame(frame);phase=['fight','open','arrival'].includes(p.phase)?p.phase:'fight';opening=phase==='fight'?0:1;travel=phase==='arrival'?1:0;ui();draw()}
ui();draw();restore(window.openai?.widgetState);window.addEventListener('openai:set_globals',e=>restore(e.detail?.globals?.widgetState));
window.addEventListener('pagehide',()=>{disposed=true;cancelAnimationFrame(frame)},{once:true});
})().catch(()=>{const r=document.getElementById('br-rail');r.querySelector('.rr-status').textContent='Preview art did not load. Reload to retry.'});
